import json
import pandas as pd

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]

FIELD_MAP = {
    "user_id": ["user_id", "id", "userId"],
    "email": ["email", "email_address"],
    "name": ["full_name", "name", "userName"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

OUTPUT_COLUMNS = ["user_id", "name", "email", "created_date", "status"]


def normalize_status(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = str(value).strip()
    if text.lower() in {"true", "1", "yes", "active"}:
        return "active"
    if text.lower() in {"false", "0", "no", "inactive"}:
        return "inactive"
    return text


def normalize_date(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    text = str(value).strip()
    if not text:
        return None
    return pd.to_datetime(text).strftime("%Y-%m-%d")


def normalize_user_id(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    return int(value)


def load_source(path):
    if path.endswith(".json"):
        return pd.read_json(path)
    if path.endswith(".csv"):
        return pd.read_csv(path)
    if path.endswith(".parquet"):
        return pd.read_parquet(path)
    raise ValueError(f"Unsupported file type: {path}")


def unify(df):
    records = []
    columns = set(df.columns)
    for _, row in df.iterrows():
        record = {}
        for unified, candidates in FIELD_MAP.items():
            value = None
            for candidate in candidates:
                if candidate in columns:
                    value = row[candidate]
                    break
            if unified == "user_id":
                value = normalize_user_id(value)
            elif unified == "created_date":
                value = normalize_date(value)
            elif unified == "status":
                value = normalize_status(value)
            elif value is not None and not (isinstance(value, float) and pd.isna(value)):
                value = str(value).strip()
            else:
                value = None
            record[unified] = value
        records.append(record)
    return records


def main():
    source_records = {}
    for source_name, path in SOURCES:
        df = load_source(path)
        source_records[source_name] = {}
        for record in unify(df):
            if record["user_id"] is not None:
                source_records[source_name][record["user_id"]] = record

    all_user_ids = sorted(
        {uid for records in source_records.values() for uid in records}
    )

    merged_rows = []
    conflicts = []

    for user_id in all_user_ids:
        merged = {"user_id": user_id}
        for field in OUTPUT_COLUMNS[1:]:
            values = {}
            for source_name, _ in SOURCES:
                record = source_records[source_name].get(user_id)
                if record and record.get(field) is not None:
                    values[source_name] = record[field]

            selected = None
            for source_name, _ in SOURCES:
                if source_name in values:
                    selected = values[source_name]
                    break

            merged[field] = selected

            if len(set(values.values())) > 1:
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": values,
                        "selected": selected,
                    }
                )

        merged_rows.append(merged)

    merged_df = pd.DataFrame(merged_rows, columns=OUTPUT_COLUMNS)
    merged_df["user_id"] = merged_df["user_id"].astype("int64")
    merged_df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as fh:
        json.dump(report, fh, indent=2)

    print(f"Wrote {len(merged_df)} users, {len(conflicts)} conflicts")


if __name__ == "__main__":
    main()
